using System.ComponentModel.DataAnnotations;
using System.IdentityModel.Tokens.Jwt;
using EEMS.Api.Authorization;using EEMS.Api.Polling;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace EEMS.Api.Controllers;
[ApiController][Authorize][Route("api/v1/elections/{electionId:guid}/polling-centers")]
public sealed class PollingController(PollingOperationsService operations):ControllerBase
{
    [HttpGet("lookups")][Authorize(Policy=PermissionCodes.PollingRead)]public async Task<ActionResult<PollingLookups>> GetLookups(Guid electionId,CancellationToken token)=>Ok(await operations.GetLookupsAsync(token));
    [HttpGet][Authorize(Policy=PermissionCodes.PollingRead)]public async Task<ActionResult<PagedResult<CenterDirectoryItem>>> GetCenters(Guid electionId,[FromQuery]string? search,[FromQuery]bool? verified,[FromQuery]int page=1,[FromQuery]int pageSize=20,CancellationToken token=default)=>Ok(await operations.GetCentersAsync(electionId,search,verified,Math.Max(1,page),Math.Clamp(pageSize,1,100),token));
    [HttpGet("{electionCenterId:guid}")][Authorize(Policy=PermissionCodes.PollingRead)]public async Task<ActionResult<CenterDetail>> GetCenter(Guid electionId,Guid electionCenterId,CancellationToken token){var item=await operations.GetCenterAsync(electionId,electionCenterId,token);return item is null?NotFound():Ok(item);}
    [HttpPost("{electionCenterId:guid}/booths")][Authorize(Policy=PermissionCodes.PollingManage)]public async Task<ActionResult<BoothSummary>> AddBooth(Guid electionId,Guid electionCenterId,AddBoothRequest request,CancellationToken token){var item=await operations.AddBoothAsync(electionId,electionCenterId,request.Code,request.Name,token);return item is null?BadRequest(new{error="invalid_or_duplicate_booth"}):Ok(item);}
    [HttpPost("{electionCenterId:guid}/verify")][Authorize(Policy=PermissionCodes.PollingManage)]public async Task<ActionResult<VerificationSummary>> Verify(Guid electionId,Guid electionCenterId,CancellationToken token){if(!TryUserId(out var userId))return Unauthorized();var item=await operations.VerifyAsync(electionId,electionCenterId,userId,token);return item is null?NotFound():Ok(item);}
    [HttpPut("{electionCenterId:guid}/agents/{assignmentId:guid}/deactivate")][Authorize(Policy=PermissionCodes.PollingManage)]public async Task<IActionResult> DeactivateAgent(Guid electionId,Guid electionCenterId,Guid assignmentId,CancellationToken token)=>await operations.DeactivateAgentAsync(electionId,electionCenterId,assignmentId,token)?NoContent():NotFound();
    [HttpPost("{electionCenterId:guid}/checklists")][Authorize(Policy=PermissionCodes.PollingManage)]public async Task<ActionResult<ChecklistSummary>> CreateChecklist(Guid electionId,Guid electionCenterId,CreateChecklistRequest request,CancellationToken token){var item=await operations.CreateChecklistAsync(electionId,electionCenterId,new CreateChecklistCommand(request.Name,request.Requirements),token);return item is null?BadRequest(new{error="invalid_checklist"}):Ok(item);}
    [HttpPut("{electionCenterId:guid}/checklists/{checklistId:guid}/items/{itemId:guid}/complete")][Authorize(Policy=PermissionCodes.PollingManage)]public async Task<ActionResult<ChecklistSummary>> CompleteItem(Guid electionId,Guid electionCenterId,Guid checklistId,Guid itemId,CompleteChecklistItemRequest request,CancellationToken token){if(!TryUserId(out var userId))return Unauthorized();var item=await operations.CompleteChecklistItemAsync(electionId,electionCenterId,checklistId,itemId,userId,request.ExpectedVersion,token);return item is null?Conflict(new{error="invalid_item_or_version"}):Ok(item);}
    private bool TryUserId(out Guid userId)=>Guid.TryParse(User.FindFirst(JwtRegisteredClaimNames.Sub)?.Value,out userId);
}
public sealed record AddBoothRequest([Required,MaxLength(50)]string Code,[Required,MaxLength(120)]string Name);public sealed record CreateChecklistRequest([Required,MaxLength(180)]string Name,[MinLength(1)]IReadOnlyList<string> Requirements);public sealed record CompleteChecklistItemRequest(int ExpectedVersion);
